  var flows=[
    {name:'The usual case',why:'One delete, then other people and an ingest run keep working, then undo.',stages:usual},
    {name:'A neighbour is deleted later',why:'A second delete removes a node that arrows of the first delete need.',stages:neighbour},
    {name:'The parent is deleted later',why:'A second delete removes the parent of the first deleted subtree.',stages:parentGone},
    {name:'The recreated node is deleted again',why:'Two old versions of one name end up in two journals. The most recent writer of each field wins.',stages:twice},
    {name:'A person moved an arrow away',why:'A person re-points an arrow that undo would otherwise put back.',stages:moved},
    {name:'The recreated node was moved',why:'A person moves the recreated node under another parent.',stages:elsewhere}
  ];

  function tagSpans(d){
    if(!d.own.length && !d.inh.length) return '<tspan class="tg-none">no tags</tspan>';
    var out=[],fresh=d.fresh||[];
    d.own.forEach(function(t){out.push([t,'tg-own'+(fresh.indexOf(t)>=0?' tg-new':'')])});
    d.inh.forEach(function(t){out.push([t,'tg-inh'+(fresh.indexOf(t)>=0?' tg-new':'')])});
    return out.map(function(p,i){return '<tspan class="'+p[1]+'"'+(i?' dx="5"':'')+'>'+p[0]+'</tspan>'}).join('');
  }
  function drawNode(d){
    var x=slot[d.s][0],y=slot[d.s][1],st=d.state||'live',chg=d.chg||{},o='';
    if(d.shadow) o+='<rect class="ghostbox" x="'+(x-6)+'" y="'+(y-6)+'" width="'+W+'" height="'+H+'" rx="6"/>';
    o+='<g class="node '+st+'"><rect class="nb" x="'+x+'" y="'+y+'" width="'+W+'" height="'+H+'" rx="6"/>';
    o+='<text class="nm" x="'+(x+9)+'" y="'+(y+18)+'">'+full[d.s]+'</text>';
    o+='<text class="id'+(d.newId?' idnew':'')+'" x="'+(x+W-9)+'" y="'+(y+18)+'" text-anchor="end">'+d.id+'</text>';
    var ov=d.owner?'<tspan dx="4">'+d.owner+'</tspan>':'<tspan class="none" dx="4">'+(d.ownerSet?'none, on purpose':'none')+'</tspan>';
    var ty=d.ty?'<tspan class="lb'+(chg.ty?' hot':'')+'">'+d.ty+' ·</tspan>':'';
    o+='<text class="fl'+(chg.owner?' chg':'')+'" x="'+(x+9)+'" y="'+(y+33)+'">'+ty+'<tspan class="lb"'+(d.ty?' dx="4"':'')+'>owner</tspan>'+ov+'</text>';
    o+='<text class="fl'+(chg.desc?' chg':'')+'" x="'+(x+9)+'" y="'+(y+47)+'">'+(d.desc?d.desc:'<tspan class="none">no description</tspan>')+'</text>';
    o+='<text class="tg" x="'+(x+9)+'" y="'+(y+63)+'">'+tagSpans(d)+'</text></g>';
    if(d.note) o+='<text class="note '+st+'" x="'+(x+2)+'" y="'+(y-(d.shadow?11:7))+'">'+d.note+'</text>';
    return o;
  }
  var MK={res:'ah-res',mer:'ah-mer',skp:'ah-skp'};
  function drawEdge(d){
    return '<path class="edge '+d.k+' '+d.st+'" d="'+paths[d.a+'>'+d.b]+'" marker-end="url(#'+(MK[d.st]||'ah')+')"/>';
  }
  function val(v){return typeof v==='function'?v():v}

  var svg=document.getElementById('story'),txt=document.getElementById('storytext'),ft=document.getElementById('fieldtable'),
      flowtabs=document.getElementById('flowtabs'),stagetabs=document.getElementById('stagetabs'),why=document.getElementById('flowwhy');
  var cur={f:0,s:0};
  function buttons(list,sel,label){
    return list.map(function(it,i){return '<button role="tab" data-i="'+i+'" aria-selected="'+(i===sel?'true':'false')+'">'+label(it,i)+'</button>'}).join('');
  }
  function render(){
    var fl=flows[cur.f],s=fl.stages[cur.s];
    flowtabs.innerHTML=buttons(flows,cur.f,function(it){return it.name});
    stagetabs.innerHTML=buttons(fl.stages,cur.s,function(it,i){return (i+1)+' · '+it.tab});
    why.textContent=fl.why;
    svg.innerHTML=val(s.edges).map(drawEdge).join('')+val(s.nodes).map(drawNode).join('');
    svg.setAttribute('aria-label',fl.name+', step '+(cur.s+1)+': '+s.title);
    txt.innerHTML='<h4>'+s.title+'</h4><ul>'+s.text.map(function(t){return '<li>'+t+'</li>'}).join('')+'</ul>';
    ft.innerHTML=s.table||'';
  }
  function pick(ev){var b=ev.target.closest('button');return b?+b.dataset.i:-1}
  flowtabs.addEventListener('click',function(ev){var i=pick(ev);if(i<0)return;cur.f=i;cur.s=0;render()});
  stagetabs.addEventListener('click',function(ev){var i=pick(ev);if(i<0)return;cur.s=i;render()});
  render();
})();
</script>

</body></html>

