// Run the page's script against a stub DOM and click through every story and step of both steppers.
const fs = require('fs');
const html = fs.readFileSync(process.argv[2], 'utf8');
const script = html.match(/<script>([\s\S]*?)<\/script>/)[1];
const ids = [...html.matchAll(/id="([a-z]+)"/g)].map(m => m[1]);
const els = {};
function el(id) {
  if (!ids.includes(id)) throw new Error('script asks for #' + id + ' but the page has no such element');
  return els[id] || (els[id] = { innerHTML: '', textContent: '', attrs: {}, handlers: {},
    setAttribute(k, v) { this.attrs[k] = v; }, addEventListener(t, f) { this.handlers[t] = f; } });
}
global.document = { getElementById: el };
eval(script);
const click = (id, i) => els[id].handlers.click({ target: { closest: () => ({ dataset: { i: String(i) } }) } });
let steps = 0, problems = [];
for (const p of ['', 'r']) {
  const nFlows = (els[p + 'flowtabs'].innerHTML.match(/<button/g) || []).length;
  for (let f = 0; f < nFlows; f++) {
    click(p + 'flowtabs', f);
    const nStages = (els[p + 'stagetabs'].innerHTML.match(/<button/g) || []).length;
    for (let s = 0; s < nStages; s++) {
      click(p + 'stagetabs', s);
      steps++;
      const where = (p ? 'redo' : 'undo') + ' story ' + (f + 1) + ' step ' + (s + 1);
      for (const part of ['story', 'storytext', 'fieldtable', 'flowwhy']) {
        const e = els[p + part], text = e.innerHTML + e.textContent;
        if (/undefined|NaN|null<|\[object/.test(text)) problems.push(where + ': bad text in #' + p + part);
      }
      if (!/<g class="node/.test(els[p + 'story'].innerHTML)) problems.push(where + ': no nodes drawn');
      if (!/<h4>/.test(els[p + 'storytext'].innerHTML)) problems.push(where + ': no text');
    }
    if (p) console.log('  redo story ' + (f + 1) + ': ' + nStages + ' steps');
  }
  console.log((p ? 'redo' : 'undo') + ' stepper: ' + nFlows + ' stories');
}
console.log(steps + ' steps rendered, ' + problems.length + ' problems');
problems.forEach(x => console.log('  ' + x));
process.exit(problems.length ? 1 : 0);
EOF
