import sys, html.parser, collections
class Count(html.parser.HTMLParser):
    VOID = {"br","meta","link","img","input","hr","path","rect","line","circle","polygon","use","stop"}
    def __init__(self): super().__init__(); self.depth = collections.Counter()
    def handle_starttag(self, tag, attrs):
        if tag not in self.VOID: self.depth[tag] += 1
    def handle_endtag(self, tag):
        if tag not in self.VOID: self.depth[tag] -= 1
p = Count(); p.feed(open(sys.argv[1], encoding="utf-8").read())
print("unbalanced tags:", {k: v for k, v in p.depth.items() if v} or "none")
